<?php
require_once "../includes/config.php";require_once "../includes/auth.php";requireRole("counsellor");
$id=currentUserId();
$stmt=$conn->prepare("SELECT full_name FROM users WHERE id=?");$stmt->bind_param("i",$id);$stmt->execute();$user=$stmt->get_result()->fetch_assoc();$stmt->close();
$stmt=$conn->prepare("SELECT COUNT(*) total FROM appointment_slots WHERE counsellor_id=? AND status='available' AND appointment_date>=CURDATE()");$stmt->bind_param("i",$id);$stmt->execute();$slots=$stmt->get_result()->fetch_assoc()["total"];$stmt->close();
$stmt=$conn->prepare("SELECT COUNT(*) total FROM appointments WHERE counsellor_id=? AND status='pending'");$stmt->bind_param("i",$id);$stmt->execute();$pending=$stmt->get_result()->fetch_assoc()["total"];$stmt->close();
$stmt=$conn->prepare("SELECT COUNT(*) total FROM appointments WHERE counsellor_id=? AND status='confirmed'");$stmt->bind_param("i",$id);$stmt->execute();$confirmed=$stmt->get_result()->fetch_assoc()["total"];$stmt->close();
?>
